def transform(grid):
    from collections import Counter
    H,W=len(grid),len(grid[0])
    cnt=Counter(x for row in grid for x in row)
    nz={k:v for k,v in cnt.items() if k!=0}
    oc=min(nz.items(), key=lambda kv: kv[1])[0]
    obj=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==oc]
    ar,ac=obj[0]; rel=[(r-ar,c-ac) for r,c in obj]
    out=[row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            cells=[(r+dr,c+dc) for dr,dc in rel]
            if all(0<=rr<H and 0<=cc<W and grid[rr][cc]==0 for rr,cc in cells):
                for rr,cc in cells: out[rr][cc]=oc
    return out

