# Check path reachability for demo 1
# Region at rows 2-3, cols 3-5 bounded by 1s

border_val = 1
fill_val = 5  # Background color

def can_reach_edge(grid, start_r, start_c, border):
    """Check if cell can reach edge (any row=0, row=N-1, col=0, col=M-1)"""
    rows = len(grid)
    cols = len(grid[0])

    # Stack-based DFS
    stack = [(start_r, start_c)]
    visited = set()
    visited.add((start_r, start_c))

    while stack:
        r, c = stack.pop()

        # Check if at edge
        if r == 0 or r == rows-1 or c == 0 or c == cols-1:
            return True

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                continue
            if (nr, nc) not in visited and grid[nr][nc] != border:
                visited.add((nr, nc))
                stack.append((nr, nc))

    return False

# Check the filled region
print("Checking fill region (rows 2-3, cols 3-5):")
for r in range(2, 4):
    for c in range(3, 6):
        if demo1_in[r][c] != border_val:
            can = can_reach_edge(demo1_in, r, c, border_val)
            print(f"  Cell ({r}, {c}): can_reach_edge = {can}")

# Also check some background cells that are NOT filled
print("\nChecking non-filled 5-region:")
# The 5s in row 0, cols 0-4 should also not be fillable
for r in range(0, 2):
    for c in range(0, 5):
        if demo1_in[r][c] != border_val:
            can = can_reach_edge(demo1_in, r, c, border_val)
            print(f"  Cell ({r}, {c}): can_reach_edge = {can}")

# Check the right side 5s (cols 7+)
for r in range(0, 2):
    for c in range(7, 21):
